shader:
uniform vec2 center;uniform float radius,rot,moving;uniform sampler2D flow;
vec4 cell(vec2 uv){
  vec3 f=moving>0.5?(texture2D(flow,uv).rgb-vec3(0.5,0.5,0.0))*vec3(0.36,0.36,0.8):vec3(0.0);
  vec2 s=(uv-f.xy*0.9)*u_size-center;
  float ca=cos(rot),sa=sin(rot);
  vec2 q=vec2(s.x*ca+s.y*sa,-s.x*sa+s.y*ca)/radius;
  float r=length(q);
  float ring=0.0;
  for(int i=0;i<8;i++){vec3 k=u_clicks[i];
    if(k.z<1.3)ring=max(ring,(1.0-k.z/1.3)*step(abs(length((uv-k.xy)*u_size)-k.z*0.7*radius),5.0));}
  if(ring>0.0)return vec4(vec3(143.0,230.0,218.0)/255.0*ring*0.7+0.1,1.0);
  if(r>1.035)return vec4(vec3(143.0,230.0,218.0)/255.0*f.z,f.z*0.5);
  bool white=q.x-0.42*sin(3.14159265*q.y)<0.0;
  if(length(q-vec2(0.0,0.5))<0.14)white=false;
  if(length(q+vec2(0.0,0.5))<0.14)white=true;
  float grain=(sin(q.x*32.0+q.y*17.0)+cos(q.y*29.0-q.x*13.0))*0.5;
  float shade=clamp(floor((r>0.92?0.55:0.58+grain*0.12)*22.0),0.0,22.0);
  float glow=max(0.0,1.0-length(s/u_size)*2.3)+f.z*0.8;
  vec3 color=white?(vec3(196.0,208.0,206.0)+glow*vec3(59.0,47.0,49.0))/255.0
                  :(vec3(30.0,91.0,91.0)+glow*vec3(24.0,55.0,55.0))/255.0;
  return vec4(color,shade/23.0);
}
